INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5642304, 819770, 24454, '<td valign="top">Awwwwwesome!  You hit the nail right on the Heida-head!  :)</td>', 'Awwwwwesome!  You hit the nail right on the Heida-head!  :)', '2009-09-09 17:09:27.000000', NULL, 1),
(5642306, 819855, 62671, '<td valign="top">My pick for the blue.  Great shot!</td>', 'My pick for the blue.  Great shot!', '2009-09-09 17:11:50.000000', NULL, 1),
(5642308, 819780, 24454, '<td valign="top">Oh yes. You did good.  This very much has that magical Heida editing.  Awesome.</td>', 'Oh yes. You did good.  This very much has that magical Heida editing.  Awesome.', '2009-09-09 17:12:41.000000', NULL, 1),
(5642318, 819769, 24454, '<td valign="top">Aaaaauuuuughhhh!   I can''t stop looking at this.  I want it!  Can you put it up for prints???   Please???   Oh. . .if you notice a new favorite and wish list, that would be me -- and I''m serious.  I will buy this if you sell it.  10</td>', 'Aaaaauuuuughhhh!   I can''t stop looking at this.  I want it!  Can you put it up for prints???   Please???   Oh. . .if you notice a new favorite and wish list, that would be me -- and I''m serious.  I will buy this if you sell it.  10', '2009-09-09 17:18:22.000000', NULL, 1),
(5642319, 819453, 24454, '<td valign="top">oH. . .excellent!  Yes.  This is Heida all the way.</td>', 'oH. . .excellent!  Yes.  This is Heida all the way.', '2009-09-09 17:18:41.000000', NULL, 1),
(5642322, 819444, 57447, '<td valign="top">Looks like a Heida to me - good work.</td>', 'Looks like a Heida to me - good work.', '2009-09-09 17:21:35.000000', NULL, 1),
(5642329, 820095, 109649, '<td valign="top">Very, very nice. I love the reflection effect, it''s like two different angles of the same objects.. very cool visual.</td>', 'Very, very nice. I love the reflection effect, it''s like two different angles of the same objects.. very cool visual.', '2009-09-09 17:27:37.000000', NULL, 1),
(5642332, 819451, 24454, '<td valign="top">This is good!  It does look like something I think she would do.  Nice job!</td>', 'This is good!  It does look like something I think she would do.  Nice job!', '2009-09-09 17:29:50.000000', NULL, 1),
(5642368, 819625, 108580, '<td valign="top">Top Marks. Very close to her work. Should ribbon.</td>', 'Top Marks. Very close to her work. Should ribbon.', '2009-09-09 17:58:27.000000', NULL, 1),
(5642387, 819855, 45475, '<td valign="top">Freakin-aye I hope you get the blue.</td>', 'Freakin-aye I hope you get the blue.', '2009-09-09 18:26:58.000000', NULL, 1),
(5642391, 820199, 109649, '<td valign="top">I don''t know how you gut it that white without washing out so much detail, but you did it! One of my favorites from this challenge.</td>', 'I don''t know how you gut it that white without washing out so much detail, but you did it! One of my favorites from this challenge.', '2009-09-09 18:31:41.000000', NULL, 1),
(5642392, 819855, 109649, '<td valign="top">Love the concept, and the execution is superb!</td>', 'Love the concept, and the execution is superb!', '2009-09-09 18:32:11.000000', NULL, 1),
(5642393, 820201, 109649, '<td valign="top">I like the soft, almost blue light on the face, and the hi-lighting light from the left They produce a pretty cool effect.</td>', 'I like the soft, almost blue light on the face, and the hi-lighting light from the left They produce a pretty cool effect.', '2009-09-09 18:32:15.000000', NULL, 1),
(5642394, 819775, 109649, '<td valign="top">Digging the angle and colors... they are so very vibrant. Love it.</td>', 'Digging the angle and colors... they are so very vibrant. Love it.', '2009-09-09 18:32:44.000000', NULL, 1),
(5642396, 819764, 109649, '<td valign="top">Wow. Awesome use of the blur effect. I can''t tell if the rider is riding through water... but it looks like sparks!</td>', 'Wow. Awesome use of the blur effect. I can''t tell if the rider is riding through water... but it looks like sparks!', '2009-09-09 18:37:25.000000', NULL, 1),
(5642415, 819625, 18563, '<td valign="top">And we have a winner! You nailed it!!! 10</td>', 'And we have a winner! You nailed it!!! 10', '2009-09-09 19:15:51.000000', NULL, 1),
(5642424, 819855, 40718, '<td valign="top">My pick for the blue (well, if I can''t have it. ;)).  You took your own shot but clearly have heida elements in it.  Fantasy.  B&amp;W.  Burn.  10  Looking at the model this must be Juliet''s.  With your 7.5 it should be the blue.</td>', 'My pick for the blue (well, if I can''t have it. ;)).  You took your own shot but clearly have heida elements in it.  Fantasy.  B&W.  Burn.  10  Looking at the model this must be Juliet''s.  With your 7.5 it should be the blue.', '2009-09-09 19:34:03.000000', NULL, 1),
(5642436, 819530, 64446, '<td valign="top">I like the feeling and the line behind the persons. I''d like to see a lower angle, without cutting her feet and eliminating the top blownout. Very nice and well captured thoug.</td>', 'I like the feeling and the line behind the persons. I''d like to see a lower angle, without cutting her feet and eliminating the top blownout. Very nice and well captured thoug.', '2009-09-09 19:53:19.000000', NULL, 1),
(5642439, 820191, 64446, '<td valign="top">Beautiful!!! On my top 3!</td>', 'Beautiful!!! On my top 3!', '2009-09-09 19:55:54.000000', NULL, 1),
(5642442, 819748, 64446, '<td valign="top">Lovely perspective and patterns, and the nice colours pulled out. On my top 3 list!</td>', 'Lovely perspective and patterns, and the nice colours pulled out. On my top 3 list!', '2009-09-09 19:57:19.000000', NULL, 1),
(5642445, 819451, 64446, '<td valign="top">Yes, very "Heidish" style. I like it very much... will be voting later.<br/>... Love the expression, the crispy eyes, a beutiful B&amp;W portrait. On my top 3 list!</td>', 'Yes, very "Heidish" style. I like it very much... will be voting later.... Love the expression, the crispy eyes, a beutiful B&W portrait. On my top 3 list!', '2009-09-09 19:58:33.000000', NULL, 1),
(5642450, 820201, 110063, '<td valign="top">Excellent job Sasha</td>', 'Excellent job Sasha', '2009-09-09 20:09:06.000000', NULL, 1),
(5642455, 819709, 15711, '<td valign="top">This cracks me up.  Love the grunge feel and her OK FINE!! expression. LOL</td>', 'This cracks me up.  Love the grunge feel and her OK FINE!! expression. LOL', '2009-09-09 20:27:05.000000', NULL, 1),
(5642456, 820033, 15711, '<td valign="top">Loving the blues.  This is gorgeous.</td>', 'Loving the blues.  This is gorgeous.', '2009-09-09 20:27:31.000000', NULL, 1),
(5642457, 820191, 15711, '<td valign="top">Gorgeous editing to create the subtle lavender gray and hint of green and pink.  Terrific composition and focus too.  WOW</td>', 'Gorgeous editing to create the subtle lavender gray and hint of green and pink.  Terrific composition and focus too.  WOW', '2009-09-09 20:28:50.000000', NULL, 1),
(5642458, 820198, 15711, '<td valign="top">LOVELY</td>', 'LOVELY', '2009-09-09 20:30:13.000000', NULL, 1),
(5642459, 819855, 15711, '<td valign="top">Incredibly artful.  The tonal range is excellent!!!</td>', 'Incredibly artful.  The tonal range is excellent!!!', '2009-09-09 20:30:48.000000', NULL, 1),
(5642460, 820106, 15711, '<td valign="top">Pretty but a bit too vivid for a Heida shot. :~)</td>', 'Pretty but a bit too vivid for a Heida shot. :~)', '2009-09-09 20:32:05.000000', NULL, 1),
(5642462, 819453, 15711, '<td valign="top">Love the hair. Love the tones.  Her expression seems a bit forced, detracting from those positive things.</td>', 'Love the hair. Love the tones.  Her expression seems a bit forced, detracting from those positive things.', '2009-09-09 20:33:41.000000', NULL, 1),
(5642468, 819872, 100773, '<td valign="top">Came back to edit my comment:<br/> <br/>Nice photo and idea, but I feel something is missing. What I found interesting in Heidas shot is her use of sky, either it is in seascapes and landscapes like this, or in her portraiture work. You hve the colors and silhouette, but I do feel the sky is missing.</td>', 'Came back to edit my comment: Nice photo and idea, but I feel something is missing. What I found interesting in Heidas shot is her use of sky, either it is in seascapes and landscapes like this, or in her portraiture work. You hve the colors and silhouette, but I do feel the sky is missing.', '2009-09-09 20:42:34.000000', NULL, 1),
(5642470, 819830, 100773, '<td valign="top">I can''t decide on this one. Somehow I think the original is better. A black and white photo is not always best in black and white, if you have a saturation slider in your editing software, then play with it. Drag it all the way down and you''ll have black and white, drag it halfway down and see something interesting. <br/> <br/>Seljalandsfoss... I''ve seen that waterfall at DPC before, havent I? Ribbon winning free study a while back the blew my mind if I remember correctly.</td>', 'I can''t decide on this one. Somehow I think the original is better. A black and white photo is not always best in black and white, if you have a saturation slider in your editing software, then play with it. Drag it all the way down and you''ll have black and white, drag it halfway down and see something interesting.  Seljalandsfoss... I''ve seen that waterfall at DPC before, havent I? Ribbon winning free study a while back the blew my mind if I remember correctly.', '2009-09-09 20:42:49.000000', NULL, 1),
(5642474, 820161, 100773, '<td valign="top">Once you see the powerlines you don''t see anything else... Advanced editing, you could''ve removed those. The photo itself lacks of many things too. Sorry</td>', 'Once you see the powerlines you don''t see anything else... Advanced editing, you could''ve removed those. The photo itself lacks of many things too. Sorry', '2009-09-09 20:45:48.000000', NULL, 1),
(5642477, 819767, 100773, '<td valign="top">Where''s the focus? I suppose this could be similar to the blurry stuff that Heida presents, but I''m afraid to say that I feel something is missing to make it strong enough.</td>', 'Where''s the focus? I suppose this could be similar to the blurry stuff that Heida presents, but I''m afraid to say that I feel something is missing to make it strong enough.', '2009-09-09 20:46:27.000000', NULL, 1),
(5642496, 819550, 101117, '<td valign="top">There''s some strange unnatural colours here, the reflection of the moon, the almost luminous green of the grass. It''s also lacking any real subject. I get the idea of the reflection in parallel with the path, but it''s not enough to make the shot on it''s own.</td>', 'There''s some strange unnatural colours here, the reflection of the moon, the almost luminous green of the grass. It''s also lacking any real subject. I get the idea of the reflection in parallel with the path, but it''s not enough to make the shot on it''s own.', '2009-09-09 21:06:23.000000', NULL, 1),
(5642497, 819762, 101117, '<td valign="top">There seems to be some processing or effect here which has removed a lot of detail and for me ruined the shot. I would also like to see just a touch more detail in the eyes.</td>', 'There seems to be some processing or effect here which has removed a lot of detail and for me ruined the shot. I would also like to see just a touch more detail in the eyes.', '2009-09-09 21:07:36.000000', NULL, 1),
(5642501, 819787, 101117, '<td valign="top">I like this shot a lot, apart from the heavy grain, which looks like it''s been added because it''s far more obvious on the background than the model.</td>', 'I like this shot a lot, apart from the heavy grain, which looks like it''s been added because it''s far more obvious on the background than the model.', '2009-09-09 21:08:55.000000', NULL, 1),
(5642506, 820014, 101117, '<td valign="top">I think the border lets this one down a little, the shot is quite dark and moody then you have this harsh white border which actually makes it harder to look at the shot itself!</td>', 'I think the border lets this one down a little, the shot is quite dark and moody then you have this harsh white border which actually makes it harder to look at the shot itself!', '2009-09-09 21:10:42.000000', NULL, 1),
(5642509, 819733, 101117, '<td valign="top">Nice concept. Like the tones and the silhouette idea, but I don''t like the actual composition.</td>', 'Nice concept. Like the tones and the silhouette idea, but I don''t like the actual composition.', '2009-09-09 21:11:18.000000', NULL, 1),
(5642513, 819764, 101117, '<td valign="top">This is very well done, love the detail you''ve managed to capture in the cyclist against all the blur of the background!</td>', 'This is very well done, love the detail you''ve managed to capture in the cyclist against all the blur of the background!', '2009-09-09 21:12:10.000000', NULL, 1),
(5642514, 819625, 101117, '<td valign="top">It has all the elements of a Heida shot, but it doesn''t have the same mood. I think that might be down to the lighting or perhaps processing.</td>', 'It has all the elements of a Heida shot, but it doesn''t have the same mood. I think that might be down to the lighting or perhaps processing.', '2009-09-09 21:13:37.000000', NULL, 1),
(5642521, 819915, 101117, '<td valign="top">Like it, amusing amidst all the serious sombre shots!</td>', 'Like it, amusing amidst all the serious sombre shots!', '2009-09-09 21:17:29.000000', NULL, 1),
(5642523, 819775, 101117, '<td valign="top">Way over the top processing in this one for my liking. Also, it''s a little cluttered especially in the lower left.</td>', 'Way over the top processing in this one for my liking. Also, it''s a little cluttered especially in the lower left.', '2009-09-09 21:19:55.000000', NULL, 1),
(5642524, 820197, 57447, '<td valign="top">I really like the landscape Heida''s like yours.</td>', 'I really like the landscape Heida''s like yours.', '2009-09-09 21:20:48.000000', NULL, 1),
(5642525, 819849, 57447, '<td valign="top">Nice barren landscape in the Heida way.</td>', 'Nice barren landscape in the Heida way.', '2009-09-09 21:21:20.000000', NULL, 1),
(5642526, 819453, 101117, '<td valign="top">One of the nicer shots I''ve seen so far, great tones and love the serious look amidst all the flying hair!</td>', 'One of the nicer shots I''ve seen so far, great tones and love the serious look amidst all the flying hair!', '2009-09-09 21:23:49.000000', NULL, 1),
(5642527, 820034, 101117, '<td valign="top">I have to score this one highly for the humour amidst all the serious sombre shots! 8.</td>', 'I have to score this one highly for the humour amidst all the serious sombre shots! 8.', '2009-09-09 21:24:37.000000', NULL, 1),
(5642528, 820033, 57447, '<td valign="top">Heida would be proud of this.</td>', 'Heida would be proud of this.', '2009-09-09 21:24:51.000000', NULL, 1),
(5642529, 820076, 101117, '<td valign="top">I really don''t know what to say or how to vote on this one! I think I''ll give it an 8 for originality!</td>', 'I really don''t know what to say or how to vote on this one! I think I''ll give it an 8 for originality!', '2009-09-09 21:27:10.000000', NULL, 1),
(5642530, 819622, 57447, '<td valign="top">The next challenge should be in your style. 10.</td>', 'The next challenge should be in your style. 10.', '2009-09-09 21:27:28.000000', NULL, 1),
(5642536, 819625, 57447, '<td valign="top">This would be on Heida''s front page.</td>', 'This would be on Heida''s front page.', '2009-09-09 21:29:10.000000', NULL, 1),
(5642541, 819709, 101117, '<td valign="top">This is probably going to get DQ''d for the overlay but just in case it doesn''t I''m going to give it an 9 for the wonderful humour and irony, brilliantly done!</td>', 'This is probably going to get DQ''d for the overlay but just in case it doesn''t I''m going to give it an 9 for the wonderful humour and irony, brilliantly done!', '2009-09-09 21:31:03.000000', NULL, 1),
(5642554, 819660, 101117, '<td valign="top">And a stare it is indeed!</td>', 'And a stare it is indeed!', '2009-09-09 21:34:45.000000', NULL, 1),
(5642585, 819918, 23579, '<td valign="top">I like the composition and post processing. My eye keeps getting drawn to the people on the cart, but they are not in sharp focus and I end up looking at the tile in the foreground. This makes the overall picture feel unsettling.</td>', 'I like the composition and post processing. My eye keeps getting drawn to the people on the cart, but they are not in sharp focus and I end up looking at the tile in the foreground. This makes the overall picture feel unsettling.', '2009-09-09 21:59:38.000000', NULL, 1),
(5642589, 819762, 23579, '<td valign="top">It looks like the picture was not originally in focus or you used too much noise reduction in post processing.</td>', 'It looks like the picture was not originally in focus or you used too much noise reduction in post processing.', '2009-09-09 22:01:36.000000', NULL, 1),
(5642632, 820199, 109309, '<td valign="top">Nice portrait..... Not sure what that thing is she''s holding..... A Plate Maybe? 8</td>', 'Nice portrait..... Not sure what that thing is she''s holding..... A Plate Maybe? 8', '2009-09-09 22:45:24.000000', NULL, 1),
(5642636, 820033, 109309, '<td valign="top">I like the dark tones and the fog rolling across the field..... the 5 tall corn stalks really complete the look</td>', 'I like the dark tones and the fog rolling across the field..... the 5 tall corn stalks really complete the look', '2009-09-09 22:47:17.000000', NULL, 1),
(5642639, 820026, 109309, '<td valign="top">This is a good portrait... it almost has a magazine ad feel, like maybe for some new perfume..... I like it</td>', 'This is a good portrait... it almost has a magazine ad feel, like maybe for some new perfume..... I like it', '2009-09-09 22:50:11.000000', NULL, 1),
(5642642, 820203, 109309, '<td valign="top">I think this has a lot of potential but it looks way over processed. 5</td>', 'I think this has a lot of potential but it looks way over processed. 5', '2009-09-09 22:54:05.000000', NULL, 1),
(5642673, 819141, 46778, '<td valign="top">Great capture of the twist that is forming.</td>', 'Great capture of the twist that is forming.', '2009-09-09 23:24:08.000000', NULL, 1),
