(5645159, 819780, 60027, '<td valign="top">I love this picture...Great job!</td>', 'I love this picture...Great job!', '2009-09-13 02:38:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5645174, 819252, 83544, '<td valign="top">For a moment I couldn''t figure out what he was doing it seemed like he was lifting off something from his neck lol :)...I I guess he was just tired :D...anyway personaly I never rested in that kind of position, maybe if we could see his tired face and sitting on some rocks, the photo would look better that way</td>', 'For a moment I couldn''t figure out what he was doing it seemed like he was lifting off something from his neck lol :)...I I guess he was just tired :D...anyway personaly I never rested in that kind of position, maybe if we could see his tired face and sitting on some rocks, the photo would look better that way', '2009-09-13 04:56:14.000000', NULL, 1),
(5645228, 820106, 83544, '<td valign="top">very inspirative photo and great resemblence to the style of heida</td>', 'very inspirative photo and great resemblence to the style of heida', '2009-09-13 09:16:53.000000', NULL, 1),
(5645230, 820033, 103004, '<td valign="top">my favorite, feels very much Heida</td>', 'my favorite, feels very much Heida', '2009-09-13 09:22:33.000000', NULL, 1),
(5645453, 819748, 76335, '<td valign="top">Good rhythm, appealing colors, mysterious.</td>', 'Good rhythm, appealing colors, mysterious.', '2009-09-13 16:47:29.000000', NULL, 1),
(5645455, 820199, 76335, '<td valign="top">Maybe a little <i>too</i> high key. I''m reminded of Poltergeist for some reason.</td>', 'Maybe a little too high key. I''m reminded of Poltergeist for some reason.', '2009-09-13 16:48:40.000000', NULL, 1),
(5645457, 819780, 76335, '<td valign="top">Topaz? Heida? Challenge aside, the Topaz (I''m assuming it is) enhances the gritty textures to good effect.</td>', 'Topaz? Heida? Challenge aside, the Topaz (I''m assuming it is) enhances the gritty textures to good effect.', '2009-09-13 16:49:42.000000', NULL, 1),
(5645460, 820103, 76335, '<td valign="top">My pick so far (I''m a third of the way through voting).</td>', 'My pick so far (I''m a third of the way through voting).', '2009-09-13 16:51:43.000000', NULL, 1),
(5645464, 820163, 76335, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=690763" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/879/120/Copyrighted_Image_Reuse_Prohibited_690763.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/879/120/Copyrighted_Image_Reuse_Prohibited_690763.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/879/120/Copyrighted_Image_Reuse_Prohibited_690763.jpg"/></a></td>', '', '2009-09-13 16:53:03.000000', NULL, 1),
(5645465, 820076, 76335, '<td valign="top">Clearly you''re making a mockery of Heida. Clearly, it''s funny as hell!</td>', 'Clearly you''re making a mockery of Heida. Clearly, it''s funny as hell!', '2009-09-13 16:53:44.000000', NULL, 1),
(5645469, 820182, 76335, '<td valign="top">I''m wishing I never voted in this challenge, as I''m discovering I really don''t understand Heida''s style, and I''m clearly not qualified to vote on these images. So throwing some extra weight on images that are in black and white and mysterious or sublime in some way, I''m almost voting this like a free study. <br/> <br/>And I like this. Heida or no Heida, this is getting high marks from me. Great!</td>', 'I''m wishing I never voted in this challenge, as I''m discovering I really don''t understand Heida''s style, and I''m clearly not qualified to vote on these images. So throwing some extra weight on images that are in black and white and mysterious or sublime in some way, I''m almost voting this like a free study.  And I like this. Heida or no Heida, this is getting high marks from me. Great!', '2009-09-13 16:57:49.000000', NULL, 1),
(5645471, 820093, 76335, '<td valign="top">This is so creepy and unsettling, that I chuckled when I looked at the title. I don''t know how Heida-esque this is (don''t care) -- points for an original entry.</td>', 'This is so creepy and unsettling, that I chuckled when I looked at the title. I don''t know how Heida-esque this is (don''t care) -- points for an original entry.', '2009-09-13 17:00:35.000000', NULL, 1),
(5645472, 820041, 76335, '<td valign="top">Points for compositional originality.</td>', 'Points for compositional originality.', '2009-09-13 17:01:31.000000', NULL, 1),
(5645474, 819931, 76335, '<td valign="top">This bridge looks familiar...</td>', 'This bridge looks familiar...', '2009-09-13 17:02:52.000000', NULL, 1),
(5645475, 819527, 76335, '<td valign="top">Full of monolithic goodness and sterile rhythm (huh?). Great shot!</td>', 'Full of monolithic goodness and sterile rhythm (huh?). Great shot!', '2009-09-13 17:04:04.000000', NULL, 1),
(5645476, 819622, 76335, '<td valign="top">Well composed and executed but (sorry!) there''s something comical, satrical even, about her expression.</td>', 'Well composed and executed but (sorry!) there''s something comical, satrical even, about her expression.', '2009-09-13 17:06:21.000000', NULL, 1),
(5645477, 820080, 76335, '<td valign="top">I like it!</td>', 'I like it!', '2009-09-13 17:06:37.000000', NULL, 1),
(5645478, 818945, 76335, '<td valign="top">There''s a lot of subtle beauty and genuine honesty in that face, that I''m certain the heavy fisted processing wasn''t necessary. It''s a face that doesn''t need any help telling it''s story.</td>', 'There''s a lot of subtle beauty and genuine honesty in that face, that I''m certain the heavy fisted processing wasn''t necessary. It''s a face that doesn''t need any help telling it''s story.', '2009-09-13 17:09:30.000000', NULL, 1),
(5645479, 819770, 46870, '<td valign="top">lovely shot</td>', 'lovely shot', '2009-09-13 17:12:41.000000', NULL, 1),
(5645623, 820088, 96729, '<td valign="top">She has an interesting, almost odd, look about her. . . like the picture.</td>', 'She has an interesting, almost odd, look about her. . . like the picture.', '2009-09-13 18:38:43.000000', NULL, 1),
(5645748, 819738, 76335, '<td valign="top">Heida or no Heida, it''s cute. An honest moment, captured beautifully.</td>', 'Heida or no Heida, it''s cute. An honest moment, captured beautifully.', '2009-09-13 21:16:16.000000', NULL, 1),
(5646171, 819622, 39349, '<td valign="top">Excellent work capturing the feel of this challenge. I really like the dramatic sky and the wonderful landscape pulling in around this lovely subject. Well done!</td>', 'Excellent work capturing the feel of this challenge. I really like the dramatic sky and the wonderful landscape pulling in around this lovely subject. Well done!', '2009-09-14 02:03:00.000000', NULL, 1),
(5646188, 820204, 39349, '<td valign="top">You''ve captured the essence here of Heida but I think what is hurting this shot is the shallow depth of field on the foreground subject. I believe having chosen to keep him in focus would have helped create an even more dramatic effect. Exposure is great and the composition of the two is fantastic. I really like the Sun beaming through the trees and the back lit forest is amazing.</td>', 'You''ve captured the essence here of Heida but I think what is hurting this shot is the shallow depth of field on the foreground subject. I believe having chosen to keep him in focus would have helped create an even more dramatic effect. Exposure is great and the composition of the two is fantastic. I really like the Sun beaming through the trees and the back lit forest is amazing.', '2009-09-14 02:08:08.000000', NULL, 1),
(5646195, 820106, 39349, '<td valign="top">I might argue that this is too bright and clean for one of Heida''s images but I''m not about to argue with a shot that is this beautiful. I love this, well done!</td>', 'I might argue that this is too bright and clean for one of Heida''s images but I''m not about to argue with a shot that is this beautiful. I love this, well done!', '2009-09-14 02:10:20.000000', NULL, 1),
(5646453, 820078, 83544, '<td valign="top">This photo really reminds me of the anime Darker than Black I don''t know if you have seen it, great photo btw</td>', 'This photo really reminds me of the anime Darker than Black I don''t know if you have seen it, great photo btw', '2009-09-14 09:22:22.000000', NULL, 1),
(5646679, 819872, 101838, '<td valign="top">Nice picture in itself, not sure it''s in Heida''s style though. IMHO the picture would be stronger if their silhouets were against the water, not the shore - they blending with it.</td>', 'Nice picture in itself, not sure it''s in Heida''s style though. IMHO the picture would be stronger if their silhouets were against the water, not the shore - they blending with it.', '2009-09-14 14:14:20.000000', NULL, 1),
(5646811, 819785, 106665, '<td valign="top">Great capture, light and DOF</td>', 'Great capture, light and DOF', '2009-09-14 16:23:47.000000', NULL, 1),
(5646816, 819996, 106665, '<td valign="top">Excellent capture!</td>', 'Excellent capture!', '2009-09-14 16:26:53.000000', NULL, 1),
(5646818, 819444, 106665, '<td valign="top">Nice image and work.</td>', 'Nice image and work.', '2009-09-14 16:27:19.000000', NULL, 1),
